    "originalNoteExcerpt": "Ирационални уравнения: sqrt(f(x)) = g(x) <=> g(x) >= 0 и f(x) = [g(x)]^2; sqrt(f(x)) = sqrt(g(x)) <=> f(x) = g(x) >= 0. Степени и Показателна функция y = a^x (a > 0, a != 1): строго растяща при a > 1 и строго намаляваща при 0 < a < 1. Показателни уравнения: a^{f(x)} = a^{g(x)} <=> f(x) = g(x); полагане a^x = t > 0; хомогенни показателни уравнения. Логаритми: log_a(b) = c <=> a^c = b (ДМ: a > 0, a != 1, b > 0). Основно логаритмично тъждество a^{log_a(b)} = b. Правила за логаритмуване на произведение, частно и степен; формула за смяна на основата log_a(b) = log_c(b) / log_c(a). Логаритмични уравнения и неравенства (обръщане на посоката на неравенството при 0 < a < 1!).",
