    "originalNoteExcerpt": "Имунна система: Вроден (неспецифичен — кожа, лигавици, фагоцитоза от макрофаги и неутрофили, система на комплемента, интерферони) и Придобит (специфичен — Т-лимфоцити за клетъчен имунитет и В-лимфоцити / плазмоцити, синтезиращи антитела / имуноглобулини IgG, IgM, IgA, IgE за хуморален имунитет). Активен (преболедуване, ваксини) vs. Пасивен имунитет (майчини антитела, лечебен серум). Кръвни групи по системата AB0 (аглутиногени A и B по еритроцитите, аглутинини алфа и бета в плазмата) и Резус-фактор (Rh). Вируси (ДНК и РНК вируси, ретровирус HIV с обратна транскриптаза). Невробиология (потенциал на покой -70 mV, потенциал на действие +30 mV, Na+/K+ помпа, химичен синапс — ацетилхолин, норадреналин, допамин, ГАМК). Ендокринна система (хипоталамо-хипофизна ос, щитовидна жлеза — тироксин и калцитонин, надбъбречни жлези — адреналин и кортизол, панкреас — инсулин и глюкагон).",
