        "Международни универсални и отраслови организации: 1) ООН (създадена през 1945 г. в Сан Франциско, централа в Ню Йорк) със специализирани агенции: ЮНЕСКО (образование, наука и култура — Париж), ФАО (прехрана и земеделие — Рим), СЗО (здравеопазване — Женева), МВФ и Световна банка (Вашингтон), МААЕ (атомна енергия — Виена); 2) СТО (Световна търговска организация — Женева): либерализиране на световната търговия и намаляване на митата; 3) ОИСР (Организация за икономическо сътрудничество и развитие — Париж): клуб на развитите пазарни икономики; 4) ОПЕК (Организация на страните износителки на петрол, 1960 г., седалище във Виена): регулира добивните квоти и цените на суровия нефт (Саудитска Арабия, Ирак, Иран, ОАЕ, Кувейт, Венецуела, Нигерия, Алжир и др.).",
