        "Индекс на човешкото развитие (ИЧР / HDI): Изчислява се ежегодно от ПРООН (Програмата на ООН за развитие) в диапазона от $0.000$ до $1.000$ въз основа на три ключови измерителя: 1) Очаквана средна продължителност на живота при раждане (здраве и дълголетие); 2) Средна и очаквана продължителност на обучението в години (образование); 3) Брутен национален доход (БНД / GNI) на глава от населението по паритет на покупателната способност в USD (жизнен стандарт). С най-висок HDI в света (над $0.950$) са Швейцария, Норвегия, Исландия, Дания и Швеция; България е в първата група на страните с „много високо човешко развитие“ ($\\text{HDI} > 0.800$).",
        "Демографски преход, Възрастови пирамиди и Световна урбанизация: 1) Първи тип възпроизводство (в развитите страни от Европа, Северна Америка, Япония): ниска раждаемост, ниска смъртност, нисък или отрицателен естествен прираст (деמוграфска криза и застаряване — регресивна/урновидна възрастова пирамида); 2) Втори тип възпроизводство (в развиващите се страни от Субсахарска Африка и части от Азия): висока раждаемост, намаляваща смъртност и висок естествен прираст („демографски взрив“ — прогресивна/триъгълна възрастова пирамида). Над $57\\%$ от населението на Земята живее в градове, като се формират гигантски мегалополиси (Токайдо в Япония, Босваш и Чипитс в САЩ, Синята бананова дъга в Западна Европа).",
