    "originalNoteExcerpt": "Асимптотична сложност по време и памет: O(1), O(log n), O(n), O(n log n), O(n^2), O(2^n). Линейни СД: Динамичен масив, Свързан списък, Стек (LIFO — push/pop), Опашка (FIFO — enqueue/dequeue). Дървовидни структури: Двоично дърво за търсене (BST — ляво поддърво < корен < дясно поддърво), Балансирани дървета (AVL, Red-Black — O(log n)), Обхождания в дълбочина: Pre-order (Корен-Ляво-Дясно), In-order (Ляво-Корен-Дясно — дава сортирана редица при BST!), Post-order (Ляво-Дясно-Корен); Двоична пирамида (Binary Heap — Priority Queue). Хеш-таблици (O(1) средно време, колизии — Chaining и Open Addressing). Графи G=(V, E): Матрица на съседство O(V^2) vs. Списък на съседство O(V + E); Обхождане в ширина (BFS с опашка — най-къс път в непретеглен граф) и в дълбочина (DFS със стек/рекурсия); Алгоритъм на Дейкстра за най-къс път в претеглен граф с неотрицателни тегла; Минимално покриващо дърво (MST — Крускал и Прим). Динамично оптимиране.",
