        "Ценообразуване на облигации и Борсови показатели (EPS, P/E, SOFIX): Между пазарните лихвени проценти и пазарната цена на вече емитираните облигации с фиксиран купон съществува ОБРАТНА зависимост — когато пазарните лихви растат, цената на старата облигация пада под номинала (дисконт). Пазарната капитализация на компания е $\\text{Market Cap} = \\text{Брой акции} \\times \\text{Пазарна цена}$. Доходът на една акция е $\\text{EPS} = \\frac{\\text{Нетна печалба}}{\\text{Брой обикновени акции}}$, а коефициентът $\\text{P/E} = \\frac{\\text{Пазарна цена}}{\\text{EPS}}$ показва за колко години инвестицията се изплаща. Водещият индекс на Българската фондова борса е $\\text{SOFIX}$ (15-те най-ликвидни компании), а световни са $\\text{S\\&P 500}$, $\\text{NASDAQ}$ (САЩ) и $\\text{DAX}$ (Германия).",
        "Валутен пазар (FOREX), Валутен спред и Търговски баланс: Банките котират две цени за чуждестранната валута: курс „Купува“ (Bid — по-ниската цена, на която банката купува валутата от клиента) и курс „Продава“ (Ask / Offer — по-високата цена, на която банката продава валутата на клиента). Разликата $\\text{Спред} = \\text{Курс Продава} - \\text{Курс Купува} > 0$ формира дохода на банката. Поскъпването на националната валута стимулира ВНОСА, а поевтиняването ѝ стимулира ИЗНОСА (прави родните стоки по-конкурентни в чужбина).",
        "Застрахователно дело (Премия, Застрахователна сума и Франшиз): В застраховането застрахованият плаща застрахователна ПРЕМИЯ на застрахователя срещу поемане на риск и изплащане на застрахователно ОБЕЗЩЕТЕНИЕ (до лимита на застрахователната сума) при настъпване на застрахователно събитие. „Франшиз“ е договореното самоучастие на застрахования в щетата (при безусловен франшиз сумата на самоучастието се приспада от всяко обезщетение). Презастраховането е прехвърляне на част от големите рискове от застрахователя към презастрахователна компания.",
        "Тристълбов пенсионен модел на Република България: 1) I стълб — Държавно обществено осигуряване (ДОО, управлявано от НОИ на разходопокривен солидарен принцип „Pay-as-you-go“); 2) II стълб — Допълнително задължително пенсионно осигуряване (ДЗПО в Универсални пенсионни фондове — УПФ за родените след 31.12.1959 г. и Професионални пенсионни фондове — ППФ за I и II категория труд, работещи на капиталов принцип по лични партиди); 3) III стълб — Допълнително доброволно пенсионно осигуряване (ДПО с данъчни облекчения)."
