    "sourceType": "syllabus",
    "originalNoteExcerpt": "Фармацевтична технология и Лекарствени форми: Твърди (таблетки, капсули, дражета, прахове), Меки (унгвенти/мази, кремове, гелове, супозитории), Течни (разтвори, суспензии, емулсии М/В и В/М, тинктури, инфузи и декокти) и Стерилни парентерални форми (инжекционни и инфузионни разтвори — апирогенност и изотоничност: 0.9% NaCl). Фармакокинетика (ADME: Абсорбция, Разпределение, Метаболизъм в черния дроб — ефект на първото преминаване, Екскреция през бъбреците). Методи за стерилизация (автоклавиране с наситена водна пара при 121 °C и 2 atm, сух горещ въздух при 160–180 °C, мембранна филтрация 0.22 µm). Микробиологичен контрол: Оцветяване по Грам (Грам-положителни — виолетови vs. Грам-отрицателни — червени/розови), антибиограма (метод на Кирби–Бауер), коли-титър и стандарт GMP.",
